pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is treated as one attempt so the job is always called at least once.
    let max_attempts = config.max_attempts.max(1);
    let max_delay = config.max_delay_ms;
    let mut delay = config.base_delay_ms.min(max_delay);

    for attempt in 0..max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt + 1 == max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(max_delay);
            }
        }
    }

    unreachable!("the retry loop always returns from an attempt")
}

